// netlify/edge-functions/lily-edge.js
// First-party edge view counter — privacy-clean rewrite.
//
// Design rules this file follows (so it's safe to ship on any site):
//   1. SAME-ORIGIN. It POSTs to /api/lily on THIS site's own origin — never
//      to another domain. Nothing about the visitor leaves the origin they
//      are already talking to. (The site's /api/lily collector may relay
//      COARSE, already-anonymized counts onward to a central dashboard
//      server-to-server — see lily-collect.js — but that hop carries no raw
//      IP and no full user-agent.)
//   2. DOESN'T TOUCH THE PAGE. It never reads or rewrites the response body.
//      The HTML the visitor receives is byte-for-byte what the origin served
//      — no injected tags, no reconstruction. We only look at request headers
//      and the response's status/content-type.
//   3. COARSE, NOT RAW. It forwards path, referrer HOST (not full URL),
//      country, and a device class. The raw IP and full UA never leave this
//      function: the IP is folded into a daily-rotating one-way hash here at
//      the edge (for approximate unique counts) and then discarded; the UA is
//      used only in-memory for bot filtering + device class.
//   4. INVISIBLE. Nothing is added to the page — no footer, no note, no link.
//
//   Install: drop at netlify/edge-functions/lily-edge.js
//   Optional env: LILY_SITE=<short-name>, LILY_IGNORE_IPS=<csv> (self-exclude)

const BOT_RE = /\bbot\b|crawl|spider|slurp|bingpreview|facebookexternalhit|whatsapp|telegram|slackbot|discordbot|twitterbot|linkedinbot|google-inspectiontool|pagespeed|lighthouse|headlesschrome|phantomjs|puppeteer|playwright|chrome-lighthouse|gptbot|claudebot|anthropic|perplexity|ahrefs|semrush|mj12bot|dotbot|petalbot|yandex|baiduspider|applebot|duckduckbot|sogou|exabot|ia_archiver|archive\.org|monitis|uptimerobot|pingdom|statuscake|hetrix|dataprovider|netcraft|dataforseo/i;

// ---- The crawler screen (v2, 2026-11-08) --------------------------------
// His ruling: "i have to always leave out the obviously fake crawls from all
// our sites. we have to have protocols that apply evenly throughout". The
// same three tests run on every site, in this file, before anything is sent:
//   1. NO BROWSER. No user-agent at all, or no Accept-Language. Every browser
//      a person uses sends both on a page load.
//   2. A FALSE BROWSER. The user-agent claims Chrome/Edge 80+ or Firefox 90+
//      but the request lacks Sec-Fetch-Dest, which those browsers have sent on
//      every request for years; or it is a script's fetch (Sec-Fetch-Dest:
//      empty), not a page load. Safari and every iOS browser are not held to
//      this test; older iPhones never sent the header.
//   3. A DATA CENTER. The address belongs to a cloud compute provider (AWS,
//      Google Cloud, Azure, Alibaba, Tencent, Huawei, ByteDance, Hetzner, OVH
//      ...). People browse from homes, phones and offices. Cloudflare, Akamai,
//      Fastly and Google's own network are NOT listed: iCloud Private Relay,
//      WARP and Chrome's IP Protection carry real people through them.
// Visit /?lily=check to see what this file decides about your own browser.
// The ranges are generated by dreamsite/tools/lily-dc.py; re-run it there.
// DC-RANGES:BEGIN generated 2026-11-09 by dreamsite/tools/lily-dc.py - do not edit by hand
// 10678 IPv4 + 4133 IPv6 ranges: AWS, Alibaba Cloud, ByteDance / Volcengine, ColoCrossing, Contabo, DigitalOcean, G-Core, Google Cloud, Hetzner, Hostinger, Huawei Cloud, IONOS, Leaseweb, Linode / Akamai Cloud, Microsoft Azure, OVH, Oracle Cloud, Psychz, QuadraNet, Scaleway, Tencent Cloud, Vultr, Zenlayer
const DC4 = '';
const DC6 = '';
// DC-RANGES:END

function unpack(b64, wide) {
  const bin = atob(b64), n = bin.length, u = new Uint8Array(n);
  for (let i = 0; i < n; i++) u[i] = bin.charCodeAt(i);
  const dv = new DataView(u.buffer), out = [];
  if (wide) for (let i = 0; i + 16 <= n; i += 16) out.push(dv.getBigUint64(i), dv.getBigUint64(i + 8));
  else for (let i = 0; i + 8 <= n; i += 8) out.push(dv.getUint32(i), dv.getUint32(i + 4));
  return out;
}
let R4 = null, R6 = null;
function inRanges(r, x) {           // r = [start0, end0, start1, end1, ...] sorted
  let lo = 0, hi = r.length / 2 - 1;
  while (lo <= hi) {
    const m = (lo + hi) >> 1;
    if (x < r[2 * m]) hi = m - 1;
    else if (x > r[2 * m + 1]) lo = m + 1;
    else return true;
  }
  return false;
}
function ip4(s) {
  const p = s.split('.');
  if (p.length !== 4) return null;
  let n = 0;
  for (const q of p) { const v = +q; if (!(v >= 0 && v <= 255) || q === '') return null; n = n * 256 + v; }
  return n;
}
function ip6top(s) {               // first 64 bits as a BigInt
  s = s.split('%')[0];
  const [a, b] = s.includes('::') ? s.split('::') : [s, null];
  const left = a ? a.split(':') : [], right = b ? b.split(':') : [];
  const groups = b === null ? left : [...left, ...Array(8 - left.length - right.length).fill('0'), ...right];
  if (groups.length !== 8) return null;
  let n = 0n;
  for (let i = 0; i < 4; i++) n = (n << 16n) | BigInt(parseInt(groups[i] || '0', 16) || 0);
  return n;
}
function dataCenter(ip) {
  if (!ip) return false;
  try {
    const mapped = ip.match(/^::ffff:(\d+\.\d+\.\d+\.\d+)$/i);
    const v4 = ip4(mapped ? mapped[1] : ip);
    if (v4 !== null) { R4 = R4 || unpack(DC4, false); return inRanges(R4, v4); }
    const v6 = ip6top(ip);
    if (v6 !== null) { R6 = R6 || unpack(DC6, true); return inRanges(R6, v6); }
  } catch { /* an unreadable address is not evidence of anything */ }
  return false;
}

// '' = a person's browser; otherwise the reason it is not counted.
function screen(req, ua, ip) {
  if (!ua) return 'no user-agent';
  if (!req.headers.get('accept-language')) return 'no Accept-Language';
  const dest = req.headers.get('sec-fetch-dest');
  if (dest === 'empty') return 'a script fetch, not a page load';
  if (!dest && !/iPhone|iPad|iPod|Macintosh.*Version\/[\d.]+ .*Safari/.test(ua)) {
    const c = ua.match(/(?:Chrome|Edg)\/(\d+)/), f = ua.match(/Firefox\/(\d+)/);
    if (c && +c[1] >= 80) return 'claims Chrome ' + c[1] + ' without its headers';
    if (f && +f[1] >= 90) return 'claims Firefox ' + f[1] + ' without its headers';
  }
  if (dataCenter(ip)) return 'a data-center address';
  return '';
}

